#!/usr/bin/env bash
# Rerun of everything JOS-3 feeds after adding the walking speed to the air
# speed relative to the body (22 Oct 2026; jos3_protocol.body_air_speed_ms).
# Every heavy job goes through paper_adhoc/gated.sh. Paper-bound tables and
# figures go to $SCR, never into the paper folder. Old outputs are copied to
# backups_walkspeed_20261022/ first. Do not edit this file while it runs; the
# launch runs a frozen copy: REPO=<repo> bash <copy>.
set -uo pipefail
cd "${REPO:-$(dirname "$0")/..}"
R="$PWD"
SCR=${SCR:-/tmp/claude-1000/-home-harshin-files-fastUTEC-paper/98394eca-18c6-484b-8728-17aede7e7821/scratchpad/reruns/walkspeed}
LOG="$SCR/logs"; mkdir -p "$LOG"
G=paper_adhoc/gated.sh
export PYTHONUNBUFFERED=1 MPLBACKEND=Agg OMP_NUM_THREADS=6 OPENBLAS_NUM_THREADS=6 MKL_NUM_THREADS=6 NUMBA_NUM_THREADS=6
step() { name=$1; need=$2; shift 2
    echo "== $name queued ($(date '+%F %T'))"
    "$G" "ws_$name" "$need" "$@" > "$LOG/$name.log" 2>&1; rc=$?
    echo "== $name rc=$rc ($(date '+%F %T'))"; return $rc; }

B=backups_walkspeed_20261022
if [ ! -d "$B" ]; then
    echo "== backup ($(date '+%F %T'))"
    for c in MMC lisbon1 lisbon2 lisbon3 lisbon4 lisbon5 lisbon6; do
        mkdir -p "$B/$c/viz"; cp -a "run_output/$c/viz/route_jos3" "$B/$c/viz/"; done
    mkdir -p "$B/MMC/postprocessing"
    for d in departure_sweep route_measures_sweep sensitivity sensitivity_2sigma ta_heterogeneity route_robustness; do
        cp -a "run_output/MMC/postprocessing/$d" "$B/MMC/postprocessing/"; done
    cp -a run_output/impact_uniform "$B/"
fi

# 1. stage 09 on the campus and the six Lisbon cases (case configs via start.sh)
for c in MMC lisbon1 lisbon2 lisbon3 lisbon4 lisbon5 lisbon6; do
    step "stage09_$c" 2 env USE_PEDESTRIAN_WIND=1 SKIP_08=1 SOLWEIG_COMPARE=0 \
        INPUT_CASE_DIR="$R/input/$c" OUTPUT_CASE_DIR="$R/run_output/$c" CASE_NAME=$c \
        nice bash start.sh 6 || { echo "FAILED stage 09 $c"; exit 1; }
    grep -q "Pipeline complete" "$LOG/stage09_$c.log" || { echo "stage 09 $c incomplete"; exit 1; }
done
grep -h "final core temp rise" "$LOG"/stage09_MMC.log

# 2. campus departure sweeps (Fig. 9, auto-clothing figure) and route-measure sweep
step jos3_auto 2 nice python3 paper_jos3_figures.py --paper-dir "$SCR/jos3_auto"
step jos3_fixed 2 nice python3 paper_jos3_figures.py --fixed-clothing --paper-dir "$SCR/jos3_fixed"
step route_measures_sweep 4 nice bash paper_adhoc/run_route_measures_sweep.sh

# 3. uniform meteorology (Sec. 4.7, Fig. S3) and Ta heterogeneity
step sensitivity 2 nice python3 sensitivity.py
step sensitivity_2sigma 2 nice python3 sensitivity.py --ta-min 32.590 --ta-max 32.731 \
    --e-min 29.5410 --e-max 29.5438 --output-dir run_output/MMC/postprocessing/sensitivity_2sigma
step impact_uniform 2 nice python3 compute_effect_uniform.py
step uniform_figure 1 nice python3 paper_uniform_figure.py --out "$SCR/uniform/uniform_signed_error.pdf"
step ta_heterogeneity 2 nice python3 paper_ta_heterogeneity.py --paper-dir "$SCR/ta_heterogeneity"
step lisbon_routes 1 nice python3 paper_lisbon_route_table.py --out "$SCR/lisbon_routes/table_lisbon_routes.tex"

# 4. ranking Monte Carlo, all at the adopted L = 5 m except the L rows
mc() { name=$1; shift
    step "mc_$name" 6 nice -n 10 python3 paper_ranking_uncertainty.py --workers 6 \
        --departures 13 16 17 --load-offset-range -64 0 \
        --out-name "$name" --paper-dir "$SCR/mc/$name" "$@"; }
mc ws_main         --flip-model state   --offset-model beam    --correlation-length-m 5 --draws 500
mc ws_flip_only    --flip-model state   --offset-model uniform --correlation-length-m 5 --draws 500
mc ws_uniform_beam --flip-model uniform --flip-rate 0.241 --offset-model beam --correlation-length-m 5 --draws 500
mc ws_corr3m       --flip-model state   --offset-model beam    --correlation-length-m 3 --draws 500
mc ws_corr10m      --flip-model state   --offset-model beam    --correlation-length-m 10 --draws 500
mc ws_corr40m      --flip-model state   --offset-model beam    --correlation-length-m 40 --draws 500
step route_robustness 6 nice -n 10 python3 paper_adhoc/route_robustness.py --workers 6
mc ws_n2000        --flip-model state   --offset-model beam    --correlation-length-m 5 --draws 2000

# 5. tables into scratch
step tabulate 2 nice python3 paper_adhoc/tabulate_ranking_mc_state.py --out "$SCR/tables" \
    --runs ws_main ws_flip_only ws_uniform_beam ws_corr3m ws_corr10m ws_corr40m ws_n2000
step route_measures_table 1 nice python3 paper_route_measures_table.py \
    --mc run_output/MMC/postprocessing/ranking_uncertainty_ws_main --paper-dir "$SCR/route_measures"
echo "== all done ($(date '+%F %T'))"
